import argparse,base64,csv,json
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--ins',type=Path,required=True);p.add_argument('--color',action='store_true');a=p.parse_args();path=a.output/('cloud_direct_ins_color_complete.ply' if a.color else 'cloud_direct_ins_geometry.ply')
with path.open('rb') as f:
 while True:
  line=f.readline().decode('ascii').strip()
  if line.startswith('element vertex '):count=int(line.split()[-1])
  if line=='end_header':offset=f.tell();break
record_size=16 if a.color else 13
if path.stat().st_size-offset!=count*record_size:raise ValueError('PLY count mismatch')
dtype=np.dtype([('xyz','<f4',3),('rgb','u1',3),('valid','u1')]) if a.color else np.dtype([('xyz','<f4',3),('intensity','u1')])
d=np.memmap(path,mode='r',offset=offset,dtype=dtype,shape=(count,));ix=np.sort(np.random.default_rng(42).choice(count,min(count,600000),replace=False));xyz=np.asarray(d['xyz'][ix],dtype='<f4');assert np.isfinite(xyz).all();intensity=np.asarray(d['intensity'][ix],dtype='u1') if not a.color else np.asarray(d['rgb'][ix],dtype='u1');lo=xyz.min(axis=0);hi=xyz.max(axis=0)
with a.ins.open(encoding='utf-8',newline='') as f:rows=list(csv.DictReader(f))
traj=[[float(r[k]) for k in ('east_m','north_m','up_m')] for r in rows]
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>直接 INS 建图实验</title><style>html,body{margin:0;height:100%;overflow:hidden;background:#0d1117;color:white;font:14px sans-serif}#p{position:fixed;top:12px;left:12px;z-index:2;background:#0d1117ee;padding:14px;border:1px solid #555;border-radius:8px;max-width:400px}button{padding:6px;margin:3px;background:#222;color:white;border:1px solid #777;border-radius:5px}p{line-height:1.5}</style><div id="p"><b>设备 INS 直接建图 · 实验结果</b><p>灰度为 LiDAR 反射率，青线为设备轨迹。姿态外参和时间仍需标定，状态异常段已排除。</p><button onclick="view('all')">全景</button><button onclick="view('top')">顶视</button><button onclick="view('side')">侧视</button><button onclick="line.visible=!line.visible">轨迹开关</button><div id="error"></div></div><script src="https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js"></script><script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script><script>try{let bytes=Uint8Array.from(atob('__XYZ__'),c=>c.charCodeAt(0)),xyz=new Float32Array(bytes.buffer),gray=Uint8Array.from(atob('__INT__'),c=>c.charCodeAt(0)),colors=new Uint8Array(gray.length*3);for(let i=0;i<gray.length;i++){let v=Math.min(255,45+gray[i]*3);colors.set([v,v,v],3*i)}let scene=new THREE.Scene(),g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(xyz,3));g.setAttribute('color',new THREE.BufferAttribute(colors,3,true));scene.add(new THREE.Points(g,new THREE.PointsMaterial({size:.06,vertexColors:true,transparent:true,opacity:.85,depthWrite:false})));let traj=__TRAJ__,lg=new THREE.BufferGeometry().setFromPoints(traj.map(p=>new THREE.Vector3(...p)));window.line=new THREE.Line(lg,new THREE.LineBasicMaterial({color:0x33eeff}));scene.add(line);let lo=__LO__,hi=__HI__,c=lo.map((v,i)=>(v+hi[i])/2),R=Math.max(...hi.map((v,i)=>v-lo[i]))*.9+2;let camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.05,10000);camera.up.set(0,0,1);let renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);document.body.appendChild(renderer.domElement);let controls=new THREE.OrbitControls(camera,renderer.domElement);controls.target.set(...c);window.view=function(v){if(v==='top')camera.position.set(c[0],c[1]-.001,c[2]+R*1.4);else if(v==='side')camera.position.set(c[0],c[1]-R*1.4,c[2]);else camera.position.set(c[0]+R*.7,c[1]-R*.8,c[2]+R*.7);controls.update()};view('all');addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});(function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)})();}catch(e){document.getElementById('error').textContent='加载失败：'+e.message+'，请检查网络和 WebGL'}</script></html>'''
html=html.replace('青线为设备轨迹。','青线为完整设备原始轨迹，包含异常跳变。')
if a.color:
 html=html.replace('灰度为 LiDAR 反射率','颜色来自相机投影，未着色点为反射率灰度').replace("colors=new Uint8Array(gray.length*3);for(let i=0;i<gray.length;i++){let v=Math.min(255,45+gray[i]*3);colors.set([v,v,v],3*i)}","colors=gray;")
for k,v in {'__XYZ__':base64.b64encode(xyz.tobytes()).decode(),'__INT__':base64.b64encode(intensity.tobytes()).decode(),'__TRAJ__':json.dumps(traj,separators=(',',':')),'__LO__':json.dumps(lo.tolist()),'__HI__':json.dumps(hi.tolist())}.items():html=html.replace(k,v)
out=a.output/('direct_ins_color_view.html' if a.color else 'direct_ins_view.html');out.write_text(html,encoding='utf-8');print('PLY verified vertices',count,'visualized',len(xyz),'html',out)

